# Cache per-locale skompilowanych wzorców (posortowanych DESC po długości
# klucza). Bez tego apply_locale sortował słownik i kompilował setki regexów
# PRZY KAŻDYM wywołaniu — a prerender SEO woła go 3x na stronę (title +
# description + całe ciało HTML) × tysiące stron dla miast nie-PL.
_LOCALE_PATTERN_CACHE: dict = {}


def _locale_patterns(locale: str, d: list):
    """[(pl, compiled, target), ...] dla locale — zbudowane raz i cache'owane."""
    import re
    cached = _LOCALE_PATTERN_CACHE.get(locale)
    if cached is None:
        cached = [
            (pl, re.compile(rf"(?<![^\W\d]){re.escape(pl)}(?![^\W\d])"), target)
            for pl, target in sorted(d, key=lambda pair: -len(pair[0]))
        ]
        _LOCALE_PATTERN_CACHE[locale] = cached
    return cached


def apply_locale(html: str, locale: str) -> str:
    """Zastosuj tłumaczenia dla danego locale.

    Locale "pl" (lub brak) → zwróć HTML bez zmian.
    Locale "en" → słownik PL_TO_EN.
    Locale "de" → słownik PL_TO_DE (Berlin, w przyszłości Hamburg, Wien).
    Locale "cs" → słownik PL_TO_CS (Praha).
    Locale "lt" → słownik PL_TO_LT (Vilnius).
    Locale "et" → słownik PL_TO_ET (Tallinn).
    Locale "lv" → słownik PL_TO_LV (Rīga).
    Locale "nl" → słownik PL_TO_NL (Amsterdam).
    Locale "fr" → słownik PL_TO_FR (region frakcyjny, np. Paris/Lyon).
    Locale "da" → słownik PL_TO_DA (Kopenhaga, region frakcyjny).
    Locale "hu" → słownik PL_TO_HU (Budapest).
    Locale "uk" → słownik PL_TO_UK (Dніпро, Київ, Вінниця).

    Wymiana używa regex z negative lookbehind/lookahead na word characters,
    żeby pojedyncze słowa nie trafiały w identyfikatory JS lub CSS classes
    (np. "Interpelacje" wewnątrz `renderInterpelacje` nie zostanie podmienione).
    Granica word-char to litera/cyfra/_, więc "/interpelacje/" matchuje
    (slash to nie word char), "renderInterpelacje" nie matchuje.

    Sortowanie po długości DESC chroni przed kolizją krótka/długa fraza.
    Pozostałe locale → nieobsługiwane, zwrot bez zmian.
    """
    import re
    if not locale or locale.lower() == "pl":
        return html
    dictionaries = {
        "en": PL_TO_EN,
        "de": PL_TO_DE,
        "cs": PL_TO_CS,
        "lt": PL_TO_LT,
        "sk": PL_TO_SK,
        "et": PL_TO_ET,
        "lv": PL_TO_LV,
        "nl": PL_TO_NL,
        "fr": PL_TO_FR,
        "da": PL_TO_DA,
        "hu": PL_TO_HU,
        "uk": PL_TO_UK,
    }
    loc = locale.lower()
    d = dictionaries.get(loc)
    if d is None:
        return html
    out = html
    # Granica słowa = litera/underscore, ale NIE cyfra (fix 2026-06-11). Twarde
    # (?!\w) blokowało klucze-fragmenty przed liczbami, bo cyfra to word char:
    # "Wynik: za 44" nie łapał klucza "Wynik: za ", "Strona 1 z 10" nie łapał
    # " z ". [^\W\d] to word char bez cyfr (patrz _locale_patterns).
    #
    # Pre-filtr substringowy: gdy klucz w ogóle nie występuje w tekście, regex
    # i tak by nie trafił, więc pomijamy kosztowny .sub. Skraca lokalizację
    # strony SEO z ~19 ms (setki podmian) do ~0.5 ms (tylko frazy realnie
    # obecne), wynik bajt w bajt identyczny. Cascading zachowany: `pl in out`
    # sprawdzane względem bieżącego `out` (po wcześniejszych podmianach).
    for pl, pattern, target in _locale_patterns(loc, d):
        if pl not in out:
            continue
        def _replacer(_m, t=target):
            """Escape apostrophes in replacement when inside single-quoted JS string."""
            s, e = _m.start(), _m.end()
            # Scan backwards from match to detect if we're inside a single-quoted
            # JS string. The old check only caught matches directly between two
            # quotes (e.g. 'Wróć'), but missed matches inside a larger string
            # like '<p>Wróć na stronę główną →</p>' where surrounding chars are
            # > and space. We limit the scan to the current line to avoid false
            # positives from other JS strings in the full HTML. Count unescaped
            # single quotes before the match — odd count means we're inside a
            # single-quoted string.
            before = _m.string[:s]
            last_nl = before.rfind('\n')
            line_before = before[last_nl + 1:] if last_nl >= 0 else before
            cleaned = line_before.replace("\\'", "")
            if cleaned.count("'") % 2 == 1:
                return t.replace("'", "\\'")
            return t
        out = pattern.sub(_replacer, out)
    return out
